mapper.insert:
	/*AdmUserPwdChngTxnDAO.insertAdmUserPwdChngTxn 어드민사용자비밀번호변경내역 등록*/	
	INSERT INTO ADM_USER_PWD_CHNG_TXN	
       ( USER_ID ,	/* 사용자아이디 */
	     USER_PWD ,	/* 사용자비밀번호 */
	     CHNG_TMSP	/* 변경타임스탬프 */	
       )		
	VALUES ( #{userId} ,	/* 사용자아이디 */
         #{userPwd} ,	/* 사용자비밀번호 */
         SYSTIMESTAMP	/* 변경타임스탬프 */	
      )
